DIGITS = set("0123456789")


def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    # name -> [balance, frozen]
    accounts: dict[str, list] = {}
    # Each entry: list of (name, previous state or None if the account did not exist)
    history: list[list] = []
    rejected: list[int] = []

    def parse(tok):
        if not tok or any(c not in DIGITS for c in tok):
            return None
        return int(tok)

    def snap(name):
        if name in accounts:
            return (name, tuple(accounts[name]))
        return (name, None)

    def revert(record):
        for name, prev in reversed(record):
            if prev is None:
                accounts.pop(name, None)
            else:
                accounts[name] = list(prev)

    def apply(t):
        # Returns a snapshot record on success, or None on failure.
        verb = t[0]
        n = len(t)

        if verb == "open" and n == 3:
            name, amt = t[1], parse(t[2])
            if amt is None or name in accounts:
                return None
            rec = [snap(name)]
            accounts[name] = [amt, False]
            return rec

        if verb == "deposit" and n == 3:
            name, amt = t[1], parse(t[2])
            if amt is None or amt <= 0 or name not in accounts:
                return None
            rec = [snap(name)]
            accounts[name][0] += amt
            return rec

        if verb == "withdraw" and n == 3:
            name, amt = t[1], parse(t[2])
            if amt is None or amt <= 0 or name not in accounts:
                return None
            acc = accounts[name]
            if acc[1] or acc[0] < amt:
                return None
            rec = [snap(name)]
            acc[0] -= amt
            return rec

        if verb == "transfer" and n == 4:
            src, dst, amt = t[1], t[2], parse(t[3])
            if amt is None or amt <= 0 or src == dst:
                return None
            if src not in accounts or dst not in accounts:
                return None
            a = accounts[src]
            if a[1] or a[0] < amt:
                return None
            rec = [snap(src), snap(dst)]
            a[0] -= amt
            accounts[dst][0] += amt
            return rec

        if verb == "freeze" and n == 2:
            name = t[1]
            if name not in accounts or accounts[name][1]:
                return None
            rec = [snap(name)]
            accounts[name][1] = True
            return rec

        if verb == "unfreeze" and n == 2:
            name = t[1]
            if name not in accounts or not accounts[name][1]:
                return None
            rec = [snap(name)]
            accounts[name][1] = False
            return rec

        return None

    for i, op in enumerate(ops):
        t = op.split(" ")
        if t[0] == "undo":
            if len(t) == 1 and history:
                revert(history.pop())
            else:
                rejected.append(i)
            continue

        rec = apply(t)
        if rec is None:
            rejected.append(i)
        else:
            history.append(rec)

    balances = {name: acc[0] for name, acc in accounts.items()}
    return balances, rejected
